<?php
namespace Tests\Feature;
use Illuminate\Support\Facades\DB; use PHPUnit\Framework\Attributes\Test; use Tests\Concerns\AuthenticatesApi; use Tests\TestCase;
final class ApprovedDamagedStockTest extends TestCase {
 use AuthenticatesApi;
 private function request(array $a,string $m,string $u,array $b=[],bool $csrf=true){return $this->withCredentials()->withUnencryptedCookie($this->apiCookieName(),$a['token'])->json($m,$u,$b,$csrf?[$this->apiCsrfHeader()=>$a['csrf']]:[]);}
 private function fixtures():array{$w=DB::table('locations')->insertGetId(['code'=>'DS'.bin2hex(random_bytes(3)),'name'=>'Damaged warehouse','location_type'=>'damaged','is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);$p=DB::table('products')->insertGetId(['sku'=>'DS'.bin2hex(random_bytes(3)),'name'=>'Damaged product','unit_code'=>'piece','is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);DB::table('inventory_balances')->insert(['product_id'=>$p,'location_id'=>$w,'quantity_on_hand'=>10,'quantity_reserved'=>0,'average_unit_cost_egp'=>'2.5000','inventory_value_egp'=>'25.00','updated_at'=>now()]);return[$w,$p];}
 private function payload(int $w,int $p):array{return['warehouse_id'=>$w,'product_id'=>$p,'quantity'=>2,'cost_egp'=>'4.1250','idempotency_key'=>'ds-'.bin2hex(random_bytes(8))];}
 #[Test] public function approval_decreases_stock_posts_balanced_journal_and_is_idempotent():void{[$w,$p]=$this->fixtures();$a=$this->actingAsApiUser('owner',true);$x=$this->payload($w,$p);$this->request($a,'GET','/api/v1/approved-damaged-stock')->assertOk();$r=$this->request($a,'POST','/api/v1/approved-damaged-stock',$x)->assertCreated();$id=$r->json('data.item.id');$this->assertSame('4.1250',DB::table('approved_damaged_stock')->where('id',$id)->value('cost_egp'));$this->assertSame(1,DB::table('approved_damaged_stock')->where('idempotency_key',$x['idempotency_key'])->count());$this->assertSame(8,(int)DB::table('inventory_balances')->where('product_id',$p)->where('location_id',$w)->value('quantity_on_hand'));$movement=DB::table('inventory_movements')->where('source_type','approved_damaged_stock')->where('source_id',$id)->first();$this->assertNotNull($movement);$this->assertSame('damage',$movement->movement_type);$journal=DB::table('journal_entries')->where('source_type','auto_approved_damaged_stock')->where('source_id',$id)->first();$this->assertNotNull($journal);$this->assertSame('posted',$journal->status);$this->assertSame(DB::table('journal_lines')->where('journal_entry_id',$journal->id)->sum('debit_amount'),DB::table('journal_lines')->where('journal_entry_id',$journal->id)->sum('credit_amount'));$this->request($a,'POST','/api/v1/approved-damaged-stock',$x)->assertOk()->assertJsonPath('data.item.id',$id);$this->assertSame(8,(int)DB::table('inventory_balances')->where('product_id',$p)->where('location_id',$w)->value('quantity_on_hand'));$this->assertSame(1,DB::table('inventory_movements')->where('source_type','approved_damaged_stock')->where('source_id',$id)->count());$this->assertSame(1,DB::table('journal_entries')->where('source_type','auto_approved_damaged_stock')->where('source_id',$id)->count());}
 #[Test] public function read_only_is_forbidden_on_list_and_create():void{$a=$this->actingAsApiUser('read_only',true);$this->request($a,'GET','/api/v1/approved-damaged-stock')->assertStatus(403);$this->request($a,'POST','/api/v1/approved-damaged-stock',[])->assertStatus(403);}
 #[Test] public function create_without_csrf_returns_419():void{[$w,$p]=$this->fixtures();$a=$this->actingAsApiUser('owner',true);$this->request($a,'POST','/api/v1/approved-damaged-stock',$this->payload($w,$p),false)->assertStatus(419);}
 #[Test] public function create_does_not_require_finance_step_up():void{[$w,$p]=$this->fixtures();$a=$this->actingAsApiUser('owner',false);$this->request($a,'POST','/api/v1/approved-damaged-stock',$this->payload($w,$p))->assertCreated();}
 #[Test] public function validation_errors_use_error_details():void{
  [$w,$p]=$this->fixtures();$a=$this->actingAsApiUser('owner',true);
  $x=$this->payload($w,$p);unset($x['warehouse_id']);$r=$this->request($a,'POST','/api/v1/approved-damaged-stock',$x);$r->assertStatus(422);$this->assertArrayHasKey('warehouse_id',$r->json('error.details'));
  $x=$this->payload($w,$p);$x['quantity']=0;$r=$this->request($a,'POST','/api/v1/approved-damaged-stock',$x);$r->assertStatus(422);$this->assertArrayHasKey('quantity',$r->json('error.details'));
  $x=$this->payload($w,$p);$x['cost_egp']='bad';$r=$this->request($a,'POST','/api/v1/approved-damaged-stock',$x);$r->assertStatus(422);$this->assertArrayHasKey('cost_egp',$r->json('error.details'));
 }
}
